        return _extraFields(_flatTicket(
            _adoKey(t),
            _adoKey(t),
            af['System.Title'] || null,
            af['System.State'] || null,
            _assigneeName(af),
            _labelNames(af['System.Tags']),
            af['System.Description'] || null,
            null
