    /** GitHub payload → flat view; the repo-scoped key needs owner/repo context. */
    function _normalizeGithubTicket(t) {
        return _flatTicket(
            _githubKey(t),
            t.id != null ? String(t.id) : null,
            t.title || null,
            t.state || null,
            _assigneeName(t),
            _labelNames(t.labels),
            t.body || null,
            t.html_url || null
