/**
 * Check WIP Label Pre-Action
 * Checks if ticket has a work-in-progress label and stops processing if found
 * Returns false to stop processing, true to continue
 */

/**
 * Pre-action function to check for WIP label
 * 
 * @param {Object} params - Parameters from Teammate job
 * @param {Object} params.ticket - Jira ticket object
 * @param {Object} params.metadata - Job metadata containing contextId
 * @returns {boolean} false to stop processing, true to continue
 */

var configLoader = require('./configLoader.js');
var gh = require('./common/githubHelpers.js');

// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var trackersModule = require('./common/trackers.js');
var _trackerCtx = { config: null, customParams: {} };
var _trackerInst = null;
function initTracker(config, customParams) {
    _trackerCtx = { config: config || null, customParams: customParams || {} };
    _trackerInst = null;
}
function getTracker() {
    if (!_trackerInst) _trackerInst = trackersModule.createTracker(_trackerCtx.config, _trackerCtx.customParams);
    return _trackerInst;
}

// ── gh-1077 extracted pure helpers (parse/build/decide) ─────────────────────

function resolveCustomParams(params) {
    return (params.jobParams && params.jobParams.customParams) || params.customParams || {};
}

function wipLabelFor(contextId) {
    return contextId + '_wip';
}

function labelsOf(ticket) {
    return ticket.fields && ticket.fields.labels ? ticket.fields.labels : [];
}

function requireTicket(ticket) {
    if (!ticket || !ticket.key) {
        throw new Error('Ticket not found or not provided: ensure inputJql targets a valid, existing Jira ticket');
    }
}

function hasContextId(ticket, metadata) {
    return !(!ticket || !metadata || !metadata.contextId);
}

function wipSkipComment(wipLabel) {
    return 'h3. *Processing Skipped*\n\n' +
        'This ticket has the *' + wipLabel + '* label indicating work is in progress.\n' +
        'Processing will be skipped until the label is removed.\n\n' +
        '_Remove the label to allow automated processing._';

/**
 * Create Questions and Assign For Review Action
 * Creates subtasks based on AI-generated questions and assigns parent ticket for review
 */

var jiraHelpers = require('./common/jiraHelpers.js');
var aiResponseParser = require('./common/aiResponseParser.js');
var trackersModule = require('./js/common/trackers.js');
var configLoader = null;
try { configLoader = require('./js/configLoader.js'); } catch (e) { /* unit tests may omit configLoader */ }

function resolveCustomParams(params) {
    return (params && params.jobParams && params.jobParams.customParams) ||
        (params && params.customParams) || {};
}

function resolveProjectConfig(params) {
    if (!configLoader || typeof configLoader.loadProjectConfig !== 'function') {
        return null;
    }
    return configLoader.loadProjectConfig((params && params.jobParams) || params);
}

function resolveAdoWorkItemType(projectConfig) {
    var jiraCfg = projectConfig && projectConfig.jira;
    return (jiraCfg && jiraCfg.questions && jiraCfg.questions.workItemType) || 'Task';
}

function resolveQuestionLabel(projectConfig) {
    return (projectConfig && projectConfig.labels && projectConfig.labels.QUESTION) || 'question';
}

function buildJiraQuestionFields(summary, description, parentKey, priority) {
    var fieldsJson = {
        summary: summary,
        description: description,
        issuetype: { name: 'Subtask' },
        parent: { key: parentKey }
    };
    if (priority) {
        fieldsJson.priority = { name: priority };
    }
    return fieldsJson;
}

function normalizeCreatedKey(result) {
    if (typeof result === 'string' && result) {
        return result;
    }
    return jiraHelpers.extractTicketKey(result);
}

function createAdoQuestionTicket(tracker, projectKey, summary, description, parentKey, priority, projectConfig) {
    var adoType = resolveAdoWorkItemType(projectConfig);
    var questionLabel = resolveQuestionLabel(projectConfig);
    var result = tracker.createTicketWithParent(projectKey, adoType, summary, description, parentKey, {
        labels: [questionLabel]
    });
    var createdKey = normalizeCreatedKey(result);
    if (createdKey && priority) {
        try {
            tracker.setPriority(createdKey, priority);
        } catch (priorityError) {
            console.warn('Could not set priority on question ' + createdKey + ' (non-fatal):', priorityError);
        }
    }
    return createdKey;
}

function createOneQuestionSubtask(question, index, parentKey, projectKey, activeTracker, projectConfig) {
    var summary = aiResponseParser.buildSummary(question.summary, index);
    var description = aiResponseParser.buildDescription(question);
    try {
        var createdKey;
        if (activeTracker.provider() === 'ado') {
            createdKey = createAdoQuestionTicket(
                activeTracker, projectKey, summary, description, parentKey, question.priority, projectConfig
            );
        } else {
            var fieldsJson = buildJiraQuestionFields(summary, description, parentKey, question.priority);
            createdKey = normalizeCreatedKey(activeTracker.createTicketWithFields(projectKey, fieldsJson));
        }
        console.log('Created question subtask ' + (createdKey || '(unknown key)') +
            ' with priority ' + (question.priority || 'default') + ' for summary "' + summary + '"');
        return {
            summary: summary,
            priority: question.priority,
            key: createdKey
        };
    } catch (error) {
        console.error('Failed to create question subtask for summary "' + summary + '":', error);
        return {
            summary: summary,
            priority: question.priority,
            error: error.toString()
        };
    }
}

function processQuestionTickets(response, parentKey, tracker, projectConfig) {
    var questions = aiResponseParser.parseQuestionsResponse(response);
    if (questions.length === 0) {
        console.log('No follow-up questions detected, skipping ticket creation.');
        return [];
    }

    var activeTracker = tracker || trackersModule.createTracker(projectConfig || null, {});
    var projectKey = String(parentKey).split('-')[0];
    var createdTickets = [];

    questions.forEach(function (question, index) {
        createdTickets.push(
            createOneQuestionSubtask(question, index, parentKey, projectKey, activeTracker, projectConfig)
        );
    });

    return createdTickets;
}

function action(params) {
    try {
        var ticketKey = params.ticket.key;
        var initiatorId = params.initiator;
        var customParams = resolveCustomParams(params);
        var projectConfig = resolveProjectConfig(params);
        var tracker = trackersModule.createTracker(projectConfig, customParams);

        console.log('Processing ticket:', ticketKey);
        var createdQuestionTickets = processQuestionTickets(params.response, ticketKey, tracker, projectConfig);

        // Add AI-generated label
        tracker.addLabel(ticketKey, 'ai_questions_asked');

        // Use common assignForReview function for post-processing
        var assignResult = jiraHelpers.assignForReview(ticketKey, initiatorId, null, null, tracker);
        if (!assignResult.success) {
            return assignResult;
        }

        return {
            success: true,
            message: 'Ticket ' + ticketKey + ' assigned, moved to In Review, created ' +
                createdQuestionTickets.length + ' question subtasks',
            createdQuestions: createdQuestionTickets
        };
    } catch (error) {
        console.error('❌ Error:', error);
        return {
            success: false,
            error: error.toString()
        };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action: action,
        processQuestionTickets: processQuestionTickets,
        resolveCustomParams: resolveCustomParams,
        resolveProjectConfig: resolveProjectConfig,
        resolveAdoWorkItemType: resolveAdoWorkItemType,
        resolveQuestionLabel: resolveQuestionLabel,
        buildJiraQuestionFields: buildJiraQuestionFields,
        normalizeCreatedKey: normalizeCreatedKey
    };
}

/**
 * Restore Jira ticket description from changelog history.
 * Merges the last large "before accident" version with any unique content
 * found in the current (accidentally overridden) version.
 *
 * params.ticketKey  - Jira issue key, e.g. "PROJ-1234"
 */

var trackersModule = require('./js/common/trackers.js');
var configLoader = null;
try { configLoader = require('./js/configLoader.js'); } catch (e) { /* unit tests may omit configLoader */ }

var DEFAULT_TICKET_KEY = 'PROJ-1234';
var DEFAULT_JIRA_BASE_URL = 'https://example.atlassian.net';

function resolveTicketKey(params) {
    if (!params) return DEFAULT_TICKET_KEY;
    return params.ticketKey || (params.ticket && params.ticket.key) || DEFAULT_TICKET_KEY;
}

function resolveCustomParams(params) {
    return (params && params.jobParams && params.jobParams.customParams) ||
        (params && params.customParams) || {};
}

function resolveProjectConfig(params) {
    if (!configLoader || typeof configLoader.loadProjectConfig !== 'function') {
        return null;
    }
    return configLoader.loadProjectConfig((params && params.jobParams) || params);
}

function readJiraBasePathEnv() {
    try {
        var val = java.lang.System.getenv('JIRA_BASE_PATH');
        return val ? String(val).trim() : null;
    } catch (e) {
        return null;
    }
}

function resolveJiraBaseUrl(projectConfig) {
    var cfgBase = projectConfig && projectConfig.jira && projectConfig.jira.baseUrl;
    var raw = cfgBase || readJiraBasePathEnv() || DEFAULT_JIRA_BASE_URL;
    return String(raw).replace(/\/+$/, '');
}

function buildChangelogUrl(ticketKey, projectConfig) {
    return resolveJiraBaseUrl(projectConfig) + '/rest/api/3/issue/' + ticketKey + '/changelog?maxResults=100';
}

function parseChangelogPayload(raw) {
    if (typeof raw === 'string') {
        try { return JSON.parse(raw); } catch (e) { return null; }
    }
    return raw;
}

function extractDescriptionChanges(values) {
    var descChanges = [];
    var list = values || [];
    for (var i = 0; i < list.length; i++) {
        appendEntryDescriptionChanges(descChanges, list[i]);
    }
    return descChanges;
}

function resolveEntryAuthor(entry) {
    return (entry && entry.author && entry.author.displayName) ? entry.author.displayName : 'unknown';
}

function toDescriptionChangeRecord(entry, author, item) {
    if (!item || item.field !== 'description') {
        return null;
    }
    return {
        created: entry.created,
        author: author,
        fromString: item.fromString || '',
        toString: item.toString || ''
    };
}

function appendEntryDescriptionChanges(descChanges, entry) {
    var items = (entry && entry.items) || [];
    var author = resolveEntryAuthor(entry);
    for (var j = 0; j < items.length; j++) {
        var record = toDescriptionChangeRecord(entry, author, items[j]);
        if (record) {
            descChanges.push(record);
        }
    }
}


function longerText(best, candidate) {
    return candidate.length > best.length ? candidate : best;
}

function findGoldenDescription(descChanges) {
    var goldenDesc = '';
    for (var k = 0; k < descChanges.length; k++) {
        goldenDesc = longerText(goldenDesc, descChanges[k].toString);
        goldenDesc = longerText(goldenDesc, descChanges[k].fromString);
    }
    return goldenDesc;
}

function findUniqueLines(goldenDesc, currentDesc) {
    var currentLines = String(currentDesc || '').split('\n');
    var uniqueLines = [];
    for (var m = 0; m < currentLines.length; m++) {
        var trimmed = currentLines[m].trim();
        if (trimmed.length > 0 && goldenDesc.indexOf(trimmed) === -1) {
            uniqueLines.push(currentLines[m]);
        }
    }
    return uniqueLines;
}

function mergeDescriptions(goldenDesc, uniqueLines) {
    if (!uniqueLines || uniqueLines.length === 0) {
        return goldenDesc;
    }
    var sepIdx = goldenDesc.indexOf('----');
    var uniqueBlock = '\n' + uniqueLines.join('\n') + '\n';
    if (sepIdx !== -1) {
        return goldenDesc.substring(0, sepIdx) + uniqueBlock + '\n' + goldenDesc.substring(sepIdx);
    }
    return goldenDesc + uniqueBlock;
}

function updateRestoredDescription(ticketKey, mergedDesc, tracker) {
    if (typeof jira_update_description === 'function') {
        return tracker.updateDescription(ticketKey, mergedDesc);
    }
    if (typeof jira_update_ticket === 'function') {
        return jira_update_ticket(ticketKey, {
            fields: { description: mergedDesc }
        });
    }
    return tracker.updateDescription(ticketKey, mergedDesc);
}

function buildUnsupportedResult(provider) {
    return {
        success: false,
        error: 'restoreDescription is not supported on the "' + provider +
            '" tracker provider (requires Jira changelog history)'
    };
}

function action(params) {
    var ticketKey = resolveTicketKey(params);
    var customParams = resolveCustomParams(params);
    var projectConfig = resolveProjectConfig(params);
    var tracker = trackersModule.createTracker(projectConfig, customParams);
    var provider = tracker.provider();

    if (provider !== 'jira') {
        return buildUnsupportedResult(provider);
    }

    // ── 1. Fetch the full changelog ──────────────────────────────────────────
    var changelogUrl = buildChangelogUrl(ticketKey, projectConfig);
    var changelog = parseChangelogPayload(jira_execute_request(changelogUrl));

    if (!changelog || !changelog.values) {
        return { success: false, error: 'Could not fetch changelog' };
    }

    // ── 2. Collect all description changes in order ──────────────────────────
    var descChanges = extractDescriptionChanges(changelog.values);
    if (descChanges.length === 0) {
        return { success: false, error: 'No description changes found in changelog' };
    }

    // ── 3. Identify key versions ─────────────────────────────────────────────
    var currentDesc = descChanges[descChanges.length - 1].toString;
    var goldenDesc = findGoldenDescription(descChanges);

    // ── 4. Merge: take golden version, append unique lines from current ───────
    var uniqueLines = findUniqueLines(goldenDesc, currentDesc);
    var mergedDesc = mergeDescriptions(goldenDesc, uniqueLines);

    // ── 5. Update the ticket description ────────────────────────────────────
    var updateResult = updateRestoredDescription(ticketKey, mergedDesc, tracker);

    return {
        success: true,
        ticketKey: ticketKey,
        goldenLength: goldenDesc.length,
        currentLength: currentDesc.length,
        mergedLength: mergedDesc.length,
        uniqueLinesAdded: uniqueLines.length,
        uniqueLines: uniqueLines,
        updateResult: updateResult
    };
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action: action,
        resolveTicketKey: resolveTicketKey,
        resolveCustomParams: resolveCustomParams,
        resolveProjectConfig: resolveProjectConfig,
        resolveJiraBaseUrl: resolveJiraBaseUrl,
        buildChangelogUrl: buildChangelogUrl,
        parseChangelogPayload: parseChangelogPayload,
        extractDescriptionChanges: extractDescriptionChanges,
        findGoldenDescription: findGoldenDescription,
        findUniqueLines: findUniqueLines,
        mergeDescriptions: mergeDescriptions,
        updateRestoredDescription: updateRestoredDescription,
        buildUnsupportedResult: buildUnsupportedResult
    };
}

